contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticket) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticket)); require(ticket <= 1000000000000000000000000000000);
        require(ticket == 10, "ticket must be exactly 10 wei");
        require(address(this).balance >= ticket, "need enough Ether for the ticket");

        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(this).balance;

        bool reverted;
        c.play{value: ticket}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(this).balance;

        // General rule: the caller can only profit (net balance increase) if the call
        // succeeds and the pot becomes empty; any profit is at most potBefore - 1 wei.
        assert(
            balanceAfter <= balanceBefore ||
            (!reverted && potAfter == 0 && balanceAfter - balanceBefore <= potBefore - 1)
        );
    }

    receive() external payable {}
}

