pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticket) internal {
        ticket = bound(ticket, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticket = 10;
        vm.assume(address(this).balance >= ticket);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint balanceBefore = address(this).balance;
        bool reverted;
        try c.play{value: ticket}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balanceAfter = address(this).balance;
        assertTrue(balanceAfter <= balanceBefore ||
            (!reverted && potAfter == 0 && balanceAfter - balanceBefore <= potBefore - 1));
    }

    function testFuzz_run(uint256 ticket) public {
        _run(ticket);
    }

    receive() external payable {}
}
